#!/usr/bin/env python3
"""Apply only the verified Instagram pagination repair through existing SSM."""
import base64,json,pathlib,subprocess,time
files=json.loads(pathlib.Path('deployment/instagram-reader-pagination-20261030-source.json').read_text())
selected={k:files[k] for k in ['bridge/service.py','bridge/cursors.py']}
HOST_SCRIPT="import json,subprocess,pathlib,hashlib,os,time,shutil\nNAME='jesse-instagram-reader-instagram-reader-1'\nBASE='sha256:f38af98504c876d1dafc326c3c068c85802f9686d387c1115e01c70a5df53a11'\nROOT=pathlib.Path('/opt/jesse-instagram-reader')\nRELEASE=ROOT/'releases'/'pagination-825fcbf'\nIMAGE='jesse-instagram-reader-instagram-reader:pagination-825fcbf'\nBASE_TAG='jesse-instagram-reader-base:pagination-825fcbf'\ndef inspect():\n    return json.loads(subprocess.check_output(['docker','inspect',NAME],text=True))[0]\ndef sha(p):\n    return hashlib.sha256(p.read_bytes()).hexdigest()\nassert inspect()['Image']==BASE, 'Reader changed since inspection; stop without replacing it'\nexpected={'bridge/service.py':'7a24b9417493315f949df3bc7a84d9a67709c9635597009cfecd2355f6ba71da','bridge/reader.py':'d98df8fdc280ba853f9486449a7e4894557acb324355f7fc3f8291c05863a6ff','bridge/compose.yaml':'c8f250c53bddb5e6953c0c3e7268420dde80fe66e71e9e5e52c0af25554b739d'}\nfor name,digest in expected.items():\n    assert sha(ROOT/name)==digest, 'Reader source changed since inspection'\nassert set(FILES)=={'bridge/service.py','bridge/cursors.py'}\nassert not (ROOT/'bridge/cursors.py').exists(), 'New cursor module already exists; inspect before retry'\nassert not RELEASE.exists(), 'Release directory exists; inspect the previous attempt before retry'\nRELEASE.mkdir(parents=True,mode=0o700)\nfor name,body in FILES.items():\n    p=RELEASE/name\n    p.parent.mkdir(parents=True,exist_ok=True)\n    p.write_text(body)\n    compile(body,name,'exec')\nsubprocess.run(['docker','tag',BASE,BASE_TAG],check=True)\n(RELEASE/'Dockerfile').write_text('FROM '+BASE_TAG+'\\nCOPY bridge/service.py /app/bridge/service.py\\nCOPY bridge/cursors.py /app/bridge/cursors.py\\nLABEL org.opencontainers.image.revision=\"825fcbfefcba150c71b5273c26e42ae1e761c6de\"\\n')\nwith (RELEASE/'build.log').open('w') as log:\n    subprocess.run(['docker','build','--pull=false','--network=none','-t',IMAGE,str(RELEASE)],stdout=log,stderr=subprocess.STDOUT,check=True)\nsubprocess.run(['docker','run','--rm','--network','none','--memory','128m','--read-only','--cap-drop','ALL','--entrypoint','python',IMAGE,'-c','from bridge.service import create_app; from bridge.cursors import valid_inbox_cursor; assert valid_inbox_cursor(\\'{\"cursor_thread_v2_id\":1574920077232276,\"cursor_relevancy_score\":0,\"cursor_timestamp_seconds\":1770124582}\\'); print(\"Candidate imports and cursor validation passed\")'],check=True)\nassert inspect()['Image']==BASE, 'Reader changed during build'\nshutil.copy2(ROOT/'bridge/service.py',RELEASE/'service.before.py')\n(RELEASE/'service.before.py').chmod(0o600)\nsubprocess.run(['docker','create','--name','jesse-instagram-reader-pagination-rollback-825fcbf','--network','none',BASE],check=True,stdout=subprocess.DEVNULL)\noverride=RELEASE/'compose.override.yaml'\ndef compose(image):\n    override.write_text('services:\\n  instagram-reader:\\n    image: '+image+'\\n')\n    override.chmod(0o600)\n    subprocess.run(['docker','compose','-p','jesse-instagram-reader','-f',str(ROOT/'bridge/compose.yaml'),'-f',str(override),'up','-d','--no-deps','--no-build','--pull','never','instagram-reader'],cwd=ROOT/'bridge',check=True,stdout=subprocess.DEVNULL)\ndef replace_file(path,body):\n    temp=path.with_suffix(path.suffix+'.pagination-tmp')\n    temp.write_text(body)\n    temp.chmod(path.stat().st_mode & 0o777 if path.exists() else 0o644)\n    os.replace(temp,path)\nstatus_code = \"\"\"import os,json,urllib.request\nr=urllib.request.Request('http://127.0.0.1:8080/v1/status',headers={'Authorization':'Bearer '+os.environ['IG_BRIDGE_TOKEN']})\nd=json.load(urllib.request.urlopen(r,timeout=15))\nassert d.get('connected') is True and d.get('username')=='jessemcinnes_' and d.get('read_only') is True\nprint(json.dumps({k:d.get(k) for k in ['connected','username','read_only']}))\n\"\"\"\ntry:\n    for name,body in FILES.items(): replace_file(ROOT/name,body)\n    compose(IMAGE)\n    for _ in range(6):\n        result=subprocess.run(['docker','exec',NAME,'python','-c',status_code],capture_output=True,text=True)\n        if result.returncode==0:\n            print(result.stdout.strip(),flush=True)\n            break\n        time.sleep(2)\n    else: raise RuntimeError('Updated reader did not verify its existing connection')\n    running=inspect()\n    assert running['State']['Running']\n    assert running['Config']['Labels'].get('org.opencontainers.image.revision')=='825fcbfefcba150c71b5273c26e42ae1e761c6de'\n    print(json.dumps({'reader_release':'825fcbf','running':True,'image':running['Image'],'session_volume_preserved':any(m.get('Name')=='jesse-instagram-reader_instagram-session' and m['Destination']=='/data' for m in running['Mounts'])}),flush=True)\nexcept Exception:\n    replace_file(ROOT/'bridge/service.py',(RELEASE/'service.before.py').read_text())\n    (ROOT/'bridge/cursors.py').unlink(missing_ok=True)\n    compose(BASE)\n    print('Reader rollback applied; release failed',flush=True)\n    raise\n"
script='FILES='+repr(selected)+'\n'+HOST_SCRIPT
encoded=base64.b64encode(script.encode()).decode()
assert len(encoded)<60000
params={'InstanceIds':['i-09a9dd3bd749643a5'],'DocumentName':'AWS-RunShellScript','Comment':'Repair only Jesse Instagram reader JSON pagination 825fcbf','Parameters':{'commands':["python3 -c \"import base64;exec(base64.b64decode('"+encoded+"'))\""],'executionTimeout':['240']}}
def aws(*args):
    return json.loads(subprocess.check_output(['aws','--region','ap-southeast-2',*args,'--output','json'],text=True))
assert aws('sts','get-caller-identity')['Account']=='323149985112'
job=aws('ssm','send-command','--cli-input-json',json.dumps(params))['Command']['CommandId']
print('SSM command:',job,flush=True)
for _ in range(100):
    try: result=aws('ssm','get-command-invocation','--command-id',job,'--instance-id','i-09a9dd3bd749643a5')
    except subprocess.CalledProcessError: time.sleep(3); continue
    if result['Status'] not in ('Pending','InProgress','Delayed'):
        print(result.get('StandardOutputContent',''))
        print('\n'.join(line for line in result.get('StandardErrorContent','').splitlines() if len(line)<500))
        assert result['Status']=='Success',result['Status']
        break
    time.sleep(3)
else: raise RuntimeError('Inspect existing SSM command before retrying')
